'use client';

import { Calendar } from 'lucide-react';
import { useId, useState } from 'react';
import {
  Area,
  AreaChart,
  CartesianGrid,
  Line,
  ReferenceLine,
  XAxis,
} from 'recharts';

import { buttonVariants } from '@/components/ui/button';
import { ArrowDown01Icon } from './icons';
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
} from '@/components/ui/chart';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { circulationData } from '../../data';
import { cn } from '@/lib/utils';

type CirculationTimeframe = 'weekly' | 'monthly' | 'yearly';

type CirculationDataPoint = {
  timestamp: number;
  checkouts: number;
  returns: number;
};

const circulationChartConfig = {
  checkouts: {
    label: 'Checkouts',
    color: 'var(--primary)',
  },
  returns: {
    label: 'Returns',
    color: 'color-mix(in oklch, var(--primary) 55%, black)',
  },
} satisfies ChartConfig;

const chartTicks: Record<CirculationTimeframe, number[]> = {
  weekly: circulationData.weekly.map((point) => point.timestamp),
  monthly: [0, 7, 14, 21].map(
    (dayIndex) => circulationData.monthly[dayIndex].timestamp,
  ),
  yearly: circulationData.yearly
    .filter((_, month) => month % 2 === 0)
    .map((point) => point.timestamp),
};

const chartDomains: Record<CirculationTimeframe, [number, number]> = {
  weekly: [
    circulationData.weekly[0].timestamp,
    circulationData.weekly[circulationData.weekly.length - 1].timestamp,
  ],
  monthly: [
    circulationData.monthly[0].timestamp,
    circulationData.monthly[circulationData.monthly.length - 1].timestamp,
  ],
  yearly: [
    circulationData.yearly[0].timestamp,
    circulationData.yearly[circulationData.yearly.length - 1].timestamp,
  ],
};

const chartMidpoints: Record<CirculationTimeframe, number[]> = {
  weekly: getMidpoints(chartTicks.weekly, chartDomains.weekly[1]),
  monthly: getMidpoints(chartTicks.monthly, chartDomains.monthly[1]),
  yearly: getMidpoints(chartTicks.yearly, chartDomains.yearly[1]),
};

function getMidpoints(ticks: number[], domainEnd: number) {
  const points = ticks.at(-1) === domainEnd ? ticks : [...ticks, domainEnd];

  return points.slice(0, -1).map((tick, index) => {
    return tick + (points[index + 1] - tick) / 2;
  });
}

const shortWeekdayFormatter = new Intl.DateTimeFormat('en-US', {
  weekday: 'short',
  timeZone: 'UTC',
});
const shortDateFormatter = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});
const shortMonthFormatter = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  timeZone: 'UTC',
});

const chartFormatters: Record<CirculationTimeframe, (value: number) => string> =
  {
    weekly: (value) => shortWeekdayFormatter.format(value),
    monthly: (value) => shortDateFormatter.format(value),
    yearly: (value) => shortMonthFormatter.format(value),
  };

const weeklyTooltipFormatter = new Intl.DateTimeFormat('en-US', {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'UTC',
});
const datedTooltipFormatter = new Intl.DateTimeFormat('en-US', {
  month: 'short',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'UTC',
});
const monthlyTooltipFormatter = new Intl.DateTimeFormat('en-US', {
  month: 'long',
  year: 'numeric',
  timeZone: 'UTC',
});

function formatTooltipDate(timeframe: CirculationTimeframe, value: number) {
  if (timeframe === 'weekly') return weeklyTooltipFormatter.format(value);
  if (timeframe === 'monthly') return datedTooltipFormatter.format(value);
  return monthlyTooltipFormatter.format(value);
}

export function CirculationChart() {
  const [timeframe, setTimeframe] = useState<CirculationTimeframe>('weekly');
  const [activeLabel, setActiveLabel] = useState<number | null>(null);
  const gradientId = useId().replace(/:/g, '');

  return (
    <div className="flex h-full flex-col">
      <div className="flex w-full items-center justify-between">
        <h2 className="text-lg font-medium">Collection Circulation</h2>
        <DropdownMenu>
          <DropdownMenuTrigger
            className={cn(
              buttonVariants({ variant: 'ghost', size: 'lg' }),
              'text-accent-foreground capitalize',
            )}
          >
            {timeframe}
            <ArrowDown01Icon className="size-4" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-32 p-1.5 shadow-lg">
            <DropdownMenuGroup>
              {(['weekly', 'monthly', 'yearly'] as const).map((option) => (
                <DropdownMenuItem
                  key={option}
                  onClick={() => setTimeframe(option)}
                  className={cn(
                    'rounded-lg capitalize',
                    timeframe === option && 'text-primary font-medium',
                  )}
                >
                  {option}
                </DropdownMenuItem>
              ))}
            </DropdownMenuGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <ChartContainer
        config={circulationChartConfig}
        className="mt-5 aspect-auto h-72 w-full grow [&_.recharts-surface]:overflow-visible"
        onMouseDown={(event) => event.preventDefault()}
      >
        <AreaChart
          data={circulationData[timeframe]}
          accessibilityLayer={false}
          margin={{ left: 4, right: 4, top: 12, bottom: 4 }}
          style={{ overflow: 'visible' }}
          onMouseMove={(state) => {
            const label = state?.activeLabel;
            setActiveLabel(
              typeof label === 'number'
                ? label
                : label != null
                  ? Number(label)
                  : null,
            );
          }}
          onMouseLeave={() => setActiveLabel(null)}
        >
          <defs>
            <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="var(--primary)" stopOpacity={0.18} />
              <stop
                offset="95%"
                stopColor="var(--primary)"
                stopOpacity={0.02}
              />
            </linearGradient>
          </defs>
          <CartesianGrid
            vertical
            horizontal={false}
            stroke="var(--border)"
            strokeDasharray="0"
          />
          {chartMidpoints[timeframe].map((midpoint) => (
            <ReferenceLine
              key={midpoint}
              x={midpoint}
              stroke="var(--border)"
              strokeDasharray="6 6"
            />
          ))}
          <XAxis
            dataKey="timestamp"
            type="number"
            domain={chartDomains[timeframe]}
            stroke="var(--muted-foreground)"
            fontSize={14}
            tickLine={false}
            axisLine={false}
            ticks={chartTicks[timeframe]}
            minTickGap={0}
            interval={0}
            padding={{ left: 0, right: 0 }}
            tick={({ x, y, payload }) => {
              const isActive = activeLabel === payload.value;
              return (
                <text
                  x={x}
                  y={y}
                  dy={14}
                  fill={
                    isActive
                      ? 'var(--secondary-foreground)'
                      : 'var(--muted-foreground)'
                  }
                  fontSize={14}
                  textAnchor="middle"
                  className="font-medium"
                >
                  {chartFormatters[timeframe](payload.value)}
                </text>
              );
            }}
          />
          <ChartTooltip
            cursor={{
              stroke: 'var(--primary)',
              strokeWidth: 1.5,
            }}
            content={({ active, payload }) => {
              if (!active || !payload?.length) return null;

              const point = payload[0].payload as CirculationDataPoint;

              return (
                <div className="bg-foreground text-background z-50 flex min-w-40 flex-col rounded-[6px] shadow-[0px_6px_14px_rgba(24,39,75,0.12),0px_10px_32px_rgba(24,39,75,0.1)]">
                  <div className="flex items-center gap-1 px-2.5 py-1.5">
                    <Calendar className="size-3 opacity-80" />
                    <span className="text-[9px] tracking-tight opacity-90">
                      {formatTooltipDate(timeframe, point.timestamp)}
                    </span>
                  </div>
                  <div className="flex flex-col gap-2 px-2 pb-2">
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex items-center gap-1">
                        <span className="bg-primary size-1.5 shrink-0 rounded-[1px]" />
                        <span className="text-[10px] leading-[1.2] opacity-80">
                          Checkouts
                        </span>
                      </div>
                      <span className="text-[10px] leading-[1.2] font-medium">
                        {point.checkouts.toLocaleString()}
                      </span>
                    </div>
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex items-center gap-1">
                        <span className="bg-primary/60 size-1.5 shrink-0 rounded-[1px]" />
                        <span className="text-[10px] leading-[1.2] opacity-80">
                          Returns
                        </span>
                      </div>
                      <span className="text-[10px] leading-[1.2] font-medium">
                        {point.returns.toLocaleString()}
                      </span>
                    </div>
                  </div>
                </div>
              );
            }}
          />
          <Area
            type="linear"
            dataKey="checkouts"
            stroke="var(--primary)"
            strokeWidth={1.75}
            fillOpacity={1}
            fill={`url(#${gradientId})`}
            dot={false}
            activeDot={{
              r: 4,
              stroke: 'var(--primary)',
              strokeWidth: 2,
              fill: 'var(--card)',
            }}
          />
          <Line
            type="linear"
            dataKey="returns"
            stroke="color-mix(in oklch, var(--primary) 55%, black)"
            strokeWidth={1.5}
            dot={false}
            activeDot={{
              r: 4,
              stroke: 'color-mix(in oklch, var(--primary) 55%, black)',
              strokeWidth: 2,
              fill: 'var(--card)',
            }}
          />
        </AreaChart>
      </ChartContainer>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Cell, Pie, PieChart, Tooltip } from 'recharts';

export type CollectionDonutDatum = {
  name: string;
  value: number;
  fill: string;
};

type CollectionDonutChartProps = {
  data: CollectionDonutDatum[];
  total: number;
  label: string;
  size?: number;
  activeIndex?: number | null;
  onActiveIndexChange?: (index: number | null) => void;
};

export function CollectionDonutChart({
  data,
  total,
  label,
  size = 180,
  activeIndex: activeIndexProp,
  onActiveIndexChange,
}: CollectionDonutChartProps) {
  const [uncontrolledActiveIndex, setUncontrolledActiveIndex] = useState<
    number | null
  >(null);
  const isControlled = activeIndexProp !== undefined;
  const activeIndex = isControlled ? activeIndexProp : uncontrolledActiveIndex;
  const setActiveIndex = (index: number | null) => {
    if (!isControlled) setUncontrolledActiveIndex(index);
    onActiveIndexChange?.(index);
  };

  const activeDatum = activeIndex !== null ? data[activeIndex] : null;
  const displayValue = activeDatum ? activeDatum.value : total;
  const displayLabel = activeDatum ? activeDatum.name : label;

  const center = size / 2;
  // Thin deep outer rim + thicker lighter body (proportions from data values)
  const deepOuter = center - 1;
  const deepInner = deepOuter - 8;
  const lightOuter = deepInner;
  const lightInner = deepOuter - 31;
  const paddingAngle = 2.5;
  const animationDuration = 800;

  return (
    <div
      className="relative shrink-0"
      style={{ width: size, height: size }}
      onMouseDown={(event) => event.preventDefault()}
    >
      <PieChart
        width={size}
        height={size}
        margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
      >
        {/* Thick lighter inner body */}
        <Pie
          data={data}
          cx={center}
          cy={center}
          dataKey="value"
          innerRadius={lightInner}
          outerRadius={lightOuter}
          paddingAngle={paddingAngle}
          startAngle={90}
          endAngle={-270}
          stroke="none"
          isAnimationActive
          animationBegin={0}
          animationDuration={animationDuration}
          onMouseEnter={(_, index) => setActiveIndex(index)}
          onMouseLeave={() => setActiveIndex(null)}
        >
          {data.map((entry, index) => (
            <Cell
              key={`light-${index}`}
              fill={entry.fill}
              fillOpacity={0.45}
              opacity={activeIndex === null || activeIndex === index ? 1 : 0.4}
              style={{ transition: 'opacity 200ms ease-in-out' }}
            />
          ))}
        </Pie>

        {/* Thin deep outer strip — same data/angles as inner */}
        <Pie
          data={data}
          cx={center}
          cy={center}
          dataKey="value"
          innerRadius={deepInner}
          outerRadius={deepOuter}
          paddingAngle={paddingAngle}
          startAngle={90}
          endAngle={-270}
          stroke="none"
          isAnimationActive
          animationBegin={0}
          animationDuration={animationDuration}
          pointerEvents="none"
        >
          {data.map((entry, index) => (
            <Cell
              key={`deep-${index}`}
              fill={entry.fill}
              opacity={activeIndex === null || activeIndex === index ? 1 : 0.4}
              style={{ transition: 'opacity 200ms ease-in-out' }}
            />
          ))}
        </Pie>
        <Tooltip content={() => null} cursor={false} />
      </PieChart>

      <div
        className="pointer-events-none absolute flex flex-col items-center justify-center text-center"
        style={{
          width: lightInner * 2,
          height: lightInner * 2,
          top: center - lightInner,
          left: center - lightInner,
        }}
      >
        <div
          key={displayLabel}
          aria-live="polite"
          className="animate-in fade-in slide-in-from-bottom-1 animation-duration-300 flex flex-col items-center gap-0.5"
        >
          <span className="text-foreground text-[23px] leading-normal font-medium tracking-[-0.02em]">
            {displayValue.toLocaleString()}
          </span>
          <span className="text-accent-foreground text-xs leading-[1.45]">
            {displayLabel}
          </span>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { CirculationChart } from './circulation-chart';
import { CollectionDonutChart } from './collection-donut-chart';
import {
  ArrowDown01Icon,
  BookPlusIcon,
  CancelIcon,
  CheckoutIcon,
  Download01Icon,
  ReturnIcon,
  SparklesIcon,
  UserAdd02Icon,
} from './icons';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import {
  collectionOverview,
  intelligenceCards,
  metrics,
  recentActivity,
} from '../../data';
import { cn } from '@/lib/utils';

const quickActions = [
  { label: 'Checkout Items', icon: CheckoutIcon },
  { label: 'Process Return', icon: ReturnIcon },
  { label: 'Add New Item', icon: BookPlusIcon },
  { label: 'Add New Member', icon: UserAdd02Icon },
];

export function DashboardContent() {
  return (
    <>
      <DashboardHeader />
      <div className="@container/dashboard space-y-10">
        <section>
          <SectionTitle>Top Metrics</SectionTitle>
          <div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {metrics.map((metric) => (
              <MetricCard key={metric.label} {...metric} />
            ))}
          </div>
        </section>

        <section>
          <SectionTitle>Quick Actions</SectionTitle>
          <div className="mt-3 grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
            {quickActions.map((action) => (
              <Card
                key={action.label}
                className="bg-secondary text-secondary-foreground cursor-pointer rounded-lg py-0 shadow-none ring-0 transition-colors hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)]"
              >
                <CardContent className="flex h-full items-center justify-between p-3">
                  <div className="flex items-center gap-2">
                    <div className="bg-background flex size-11 items-center justify-center rounded-lg">
                      <action.icon className="size-5" />
                    </div>
                    <span className="text-secondary-foreground/80 text-base font-medium">
                      {action.label}
                    </span>
                  </div>
                  <ArrowDown01Icon className="text-muted-foreground size-6 -rotate-90 transition-transform duration-200 ease-out group-hover/card:translate-x-0.5 motion-reduce:transform-none" />
                </CardContent>
              </Card>
            ))}
          </div>
        </section>

        <section className="grid grid-cols-1 items-stretch gap-8 @4xl/dashboard:grid-cols-3">
          <div className="@4xl/dashboard:col-span-2">
            <CirculationChart />
          </div>
          <div className="min-h-84">
            <CollectionOverview />
          </div>
        </section>

        <section className="grid grid-cols-1 gap-8 @4xl/dashboard:grid-cols-2">
          <RecentActivity />
          <LibraryIntelligence />
        </section>
      </div>
    </>
  );
}

function SectionTitle({ children }: { children: React.ReactNode }) {
  return <h2 className="text-lg font-medium">{children}</h2>;
}

function DashboardHeader() {
  return (
    <div className="mb-6 flex flex-col items-start justify-between gap-4 sm:mb-10 sm:flex-row sm:items-end">
      <div className="flex flex-col gap-2">
        <h1 className="text-xl leading-[1.4] font-medium italic">
          Good Morning Librarian
        </h1>
        <div className="flex flex-col gap-2 text-base leading-[1.4] sm:flex-row sm:items-center">
          <p className="text-muted-foreground italic">
            Springfield Public Library
          </p>
          <div className="bg-foreground hidden size-1.5 rounded-full sm:inline-block" />
          <p className="text-secondary-foreground/80">Saturday, Feb 19, 2026</p>
        </div>
      </div>
      <Button
        variant="secondary"
        className="h-11 gap-3 pr-3 pl-4.5 text-[15px] font-medium tracking-[-0.02em]"
      >
        <span>Export</span>
        <Download01Icon className="size-5 -scale-y-100" />
      </Button>
    </div>
  );
}

function MetricCard({
  icon: Icon,
  iconClassName,
  label,
  note,
  noteIcon: NoteIcon,
  value,
}: {
  label: string;
  value: string;
  note: string;
  icon: React.ComponentType<{ className?: string }>;
  iconClassName: string;
  noteIcon?: React.ComponentType<{ className?: string }>;
}) {
  const noteParts = note.match(/^([+-]?\d+(?:\.\d+)?%?|↓\s*\d+)\s+(.*)$/);

  return (
    <Card className="bg-secondary text-secondary-foreground gap-6 rounded-lg p-4 shadow-none ring-0">
      <div className="flex items-center gap-2">
        <Icon className={cn('size-5 shrink-0', iconClassName)} />
        <span className="text-secondary-foreground/80 text-sm leading-[1.4] font-medium">
          {label}
        </span>
      </div>
      <div className="flex flex-col gap-3">
        <h3 className="text-foreground text-[32px] leading-none font-medium">
          {value}
        </h3>
        <p className="flex items-center gap-1 text-xs">
          {NoteIcon && <NoteIcon className="size-3.5 shrink-0" />}
          {noteParts ? (
            <>
              <span className="text-secondary-foreground font-medium">
                {noteParts[1]}
              </span>{' '}
              <span className="text-muted-foreground">{noteParts[2]}</span>
            </>
          ) : (
            <span className="text-muted-foreground">{note}</span>
          )}
        </p>
      </div>
    </Card>
  );
}

function CollectionOverview() {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const total = collectionOverview.segments.reduce(
    (sum, segment) => sum + segment.count,
    0,
  );
  const segments = collectionOverview.segments.map((segment) => ({
    ...segment,
    percentage: total > 0 ? (segment.count / total) * 100 : 0,
  }));
  const chartData = segments.map((segment) => ({
    name: segment.label,
    value: segment.count,
    fill: segment.color,
  }));

  return (
    <div className="flex h-full flex-col">
      <SectionTitle>Collection Overview</SectionTitle>
      <Card className="border-border mt-5 flex flex-1 flex-col rounded-lg border py-0 shadow-none ring-0">
        <CardContent className="flex h-full flex-col items-center justify-between gap-5 p-4 sm:flex-row sm:items-center sm:gap-8 sm:px-8 @4xl/dashboard:flex-col @4xl/dashboard:gap-5 @4xl/dashboard:px-4">
          <CollectionDonutChart
            data={chartData}
            total={total}
            label={collectionOverview.label}
            size={180}
            activeIndex={activeIndex}
            onActiveIndexChange={setActiveIndex}
          />
          <div className="flex w-full flex-col gap-2 sm:max-w-64 @4xl/dashboard:max-w-none">
            {segments.map((segment, index) => (
              <div
                key={segment.label}
                className={cn(
                  'text-secondary-foreground grid grid-cols-3 items-center text-base leading-[1.4] transition-opacity duration-200',
                  activeIndex !== null && activeIndex !== index && 'opacity-40',
                )}
              >
                <div className="text-secondary-foreground/80 flex min-w-0 items-center gap-2">
                  <span
                    className="size-3.5 shrink-0 rounded"
                    style={{ backgroundColor: segment.color }}
                  />
                  <span className="truncate">{segment.label}</span>
                </div>
                <span className="text-center font-medium tabular-nums">
                  {segment.count.toLocaleString()}
                </span>
                <span className="text-right font-medium tabular-nums">
                  {segment.percentage % 1 === 0
                    ? `${segment.percentage.toFixed(0)}%`
                    : `${segment.percentage.toFixed(1)}%`}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function RecentActivity() {
  return (
    <div>
      <SectionTitle>Recent Activity</SectionTitle>
      <div className="mt-5 flex flex-col gap-6">
        {recentActivity.map((activity) => {
          const ActivityIcon = activity.icon;
          return (
            <div key={activity.id} className="flex items-center gap-3">
              <div className="bg-secondary text-secondary-foreground flex size-11 shrink-0 items-center justify-center rounded-lg">
                <ActivityIcon className="size-5" />
              </div>
              <div className="flex min-w-0 flex-1 items-start justify-between gap-3">
                <p className="text-base leading-[1.4]">
                  {activity.parts.map((part, index) => (
                    <span
                      key={`${activity.id}-${index}`}
                      className={cn(
                        'text-secondary-foreground font-medium',
                        'muted' in part &&
                          part.muted &&
                          'text-muted-foreground font-normal',
                      )}
                    >
                      {part.text}
                    </span>
                  ))}
                </p>
                <time
                  dateTime={activity.dateTime}
                  className="text-secondary-foreground/80 shrink-0 text-sm leading-4 font-medium"
                >
                  {activity.time}
                </time>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function LibraryIntelligence() {
  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between gap-2">
        <SectionTitle>Library Intelligence</SectionTitle>
        <Button
          variant="ghost"
          size="sm"
          className="text-accent-foreground h-auto gap-1 bg-transparent px-0 py-0 hover:bg-transparent dark:hover:bg-transparent"
        >
          <span className="text-sm font-normal">See all</span>
          <ArrowDown01Icon className="size-4 -rotate-90 transition-transform duration-200 ease-out group-hover/button:translate-x-0.5 motion-reduce:transform-none" />
        </Button>
      </div>
      <div className="mt-5 flex flex-1 flex-col justify-between gap-3">
        {intelligenceCards.map((card) => (
          <Card
            key={card.title}
            className="bg-secondary text-secondary-foreground rounded-lg py-0 shadow-none ring-0"
          >
            <CardContent className="flex flex-col gap-3 p-3">
              <div className="flex items-center justify-between">
                <div
                  className={cn(
                    'flex items-center gap-1 text-sm font-semibold',
                    card.tone === 'insight' && 'text-[#c803c8]',
                    card.tone === 'warning' && 'text-[#d47c01]',
                    card.tone === 'success' && 'text-[#15823e]',
                  )}
                >
                  <SparklesIcon className="size-5" />
                  <span>{card.title}</span>
                </div>
                <Button
                  aria-label={`Dismiss ${card.title}`}
                  variant="ghost"
                  size="icon-xs"
                  className="size-5"
                >
